/* passage-rubric.js — 오늘의 지문에만 해당하는 채점 기준과 개념 정의.
   지문을 바꾸면 이 파일만 새 지문에 맞게 고치면 된다(look.js의 paras·passageTitle, views.js의 questions와 함께).
   grading.js(답안 채점·피드백), insight.js(개념 3분류), scripts/grade.mjs(Claude 채점)가 이 값을 쓴다.

   지금 지문: 호작도 속 호랑이와 까치의 의미 (26년 고1 3월 모의고사 1~3 지문, 발표문)
   문단 번호는 0부터: 0 = 1문단(도입), 1 = 2문단(수호자 호랑이), 2 = 3문단(익살스러운 호랑이·까치) */

/* 낱말 목록 + 조사: 마지막 글자에 받침이 있으면 을/이라는, 없으면 를/라는 */
const rbHas = w => { const c = w.charCodeAt(w.length - 1) - 0xac00; return c >= 0 && c < 11172 && c % 28 !== 0; };
const rbObj = list => { const w = list.join(', '); return w + (rbHas(w) ? '을' : '를'); };
const rbIra = list => { const w = list.join(', '); return w + (rbHas(w) ? '이라는' : '라는'); };
const rbList = list => list.join(', ');

